    private async Task PairAsync(HttpContext context)
    {
        if (!IsSameLan(context.Connection.RemoteIpAddress))
        {
            await WriteError(context, StatusCodes.Status403Forbidden, "é…å¯¹åªå…è®¸ä»æ•™å¸ˆç”µè„‘æ‰€åœ¨æ ¡å›­ LAN å‘èµ·ã€‚")
