                throw new InvalidDataException("å¾…å¤„ç†é…å¯¹è¯·æ±‚è¿‡å¤šï¼›è¯·åœ¨æ•™å¸ˆç«¯å…ˆå¤„ç†ç°æœ‰è¯·æ±‚ã€‚");
            var id = Guid.NewGuid();
