        foreach (var pair in supplied)
        {
            string target;
            try { target = WebsitePolicyTransport.NormalizeTargets([pair.Key]).Single(); }
            catch (InvalidDataException)
            { throw new InvalidDataException("æ‰‹æœºé¡µé¢æäº¤çš„ç­–ç•¥ç‰ˆæœ¬å¯¹åº”äº†æ— æ•ˆç”µè„‘ç›®æ ‡ï¼›è¯·åˆ·æ–°åå•åé‡è¯•ã€‚"); }
            if (pair.Value < 0 || !normalized.TryAdd(target, pair.Value))
                throw new InvalidDataException($"æ‰‹æœºé¡µé¢æäº¤çš„{policyName}ç‰ˆæœ¬æ— æ•ˆï¼›è¯·åˆ·æ–°çŠ¶æ€åé‡è¯•ã€‚");
        }
        if (normalized.Count != targets.Count || targets.Any(target => !normalized.ContainsKey(target)))
            throw new InvalidDataException($"æ‰€é€‰ç”µè„‘æˆ–{policyName}çŠ¶æ€å·²å˜åŒ–ï¼›è¯·åˆ·æ–°çŠ¶æ€å¹¶é‡æ–°ç¡®è®¤ï¼Œæœªå‘é€ç­–ç•¥ã€‚");
        if (targets.Any(target => normalized[target] != current[target]))
            throw new InvalidDataException($"æ‰€é€‰ç”µè„‘çš„{policyName}çŠ¶æ€å·²å˜åŒ–ï¼›è¯·åˆ·æ–°çŠ¶æ€å¹¶é‡æ–°ç¡®è®¤ï¼Œæœªå‘é€ç­–ç•¥ã€‚");
